// Check the book never crossed, and compare the two books batch by batch.
const run = nb.get('book_run'), ladder = nb.get('book_ladder');
if (!run || !ladder) return 'Run the Python cell first.';

const crossed = ladder.filter(s => s.bids.length && s.asks.length && s.bids[0][0] >= s.asks[0][0]).length;
console.log(ladder.length + ' snapshots: best bid below best ask in all but ' + crossed);
console.log('the heap book and the list book made the same fills: ' + run.same);
const shares = run.fillList.reduce((s, f) => s + f[1], 0);
console.log('first ' + run.fillList.length + ' fills: ' + shares.toLocaleString() + ' shares, average price ' +
  (run.fillList.reduce((s, f) => s + f[0] * f[1], 0) / shares).toFixed(4));

const rows = [];
for (const [name, costs] of Object.entries(run.costs)) {
  costs.forEach((us, b) => rows.push({ messages: (b + 1) * 500, us, book: name }));
  const sorted = [...costs].sort((a, b) => a - b);
  console.log(name.padEnd(13) + ' median ' + sorted[Math.floor(sorted.length / 2)].toFixed(2) + ' µs per message, slowest batch ' + sorted.at(-1).toFixed(2));
}
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 240,
  title: 'Microseconds per message, batch by batch (' + Math.round(run.cancels * 100) + '% cancels)',
  data: { values: rows },
  mark: { type: 'line', strokeWidth: 1.6 },
  encoding: {
    x: { field: 'messages', type: 'quantitative', title: 'messages processed' },
    y: { field: 'us', type: 'quantitative', title: 'µs per message' },
    color: { field: 'book', type: 'nominal', title: null },
  },
};
